from collections import Counter, deque

def components(grid):
 h,w=len(grid),len(grid[0]); bg=Counter(sum(grid,[])).most_common(1)[0][0]; seen=set(); comps=[]
 for r in range(h):
  for c in range(w):
   color=grid[r][c]
   if color==bg or (r,c) in seen: continue
   q=[(r,c)]; seen.add((r,c)); cells=[]
   while q:
    a,b=q.pop(); cells.append((a,b))
    for x,y in ((a+1,b),(a-1,b),(a,b+1),(a,b-1)):
     if 0<=x<h and 0<=y<w and (x,y) not in seen and grid[x][y]==color:
      seen.add((x,y)); q.append((x,y))
   rs=[x for x,y in cells]; cs=[y for x,y in cells]; area=(max(rs)-min(rs)+1)*(max(cs)-min(cs)+1)
   comps.append((color,len(cells),(min(rs),max(rs),min(cs),max(cs)),area,len(cells)/area))
 return bg,comps
bg,comps=components(grid)
print(bg)
print([x for x in comps if x[1]>=4])
